import local.cleartv.mobile.SdbClient;import java.nio.file.*;
public class InstallCheck{public static void main(String[] a)throws Exception{try(SdbClient s=new SdbClient(a[0])){byte[] file=Files.readAllBytes(Paths.get(a[1]));s.push(file,"/home/owner/share/tmp/sdk_tools/ClearMobileTest.wgt",null);String log=s.shell("0 vd_appinstall ClearTest1 /home/owner/share/tmp/sdk_tools/ClearMobileTest.wgt");System.out.println(log.substring(Math.max(0,log.length()-400)));if(!log.contains("install completed"))throw new Exception("Installation not confirmed");System.out.println(s.shell("0 execute ClearTest1.Home"));}}}
